// Read the Telerivet webhook body
const body = $json.body ?? {};

// Extract basic Telerivet fields
const rawMessage = String(body.content ?? '').trim();
const telerivetMessageId = String(body.id ?? '');
const senderNumber = String(body.from_number ?? '');
const receiverNumber = String(body.to_number ?? '');
const webhookEvent = String(body.event ?? '');
const direction = String(body.direction ?? '');

// Expected SMS format:
// BBS-MCS AUTO-2 : PFC-1 NORTH Track Feed Charger Failure  01/31/2025 07:25:35
// BBS-MCS AUTO-2 : PFC-1 NORTH Track Feed Charger Restored 01/31/2025 07:32:36

const pattern =
  /^(.*?)\s*:\s*(.*?)\s+(Failure|Restored)\s+(\d{2}\/\d{2}\/\d{4}\s+\d{2}:\d{2}:\d{2})\s*$/i;

const match = rawMessage.match(pattern);

// Return a controlled error instead of stopping the workflow
if (!match) {
  return {
    parsed_successfully: false,
    parse_error: 'SMS format not recognised',

    raw_message: rawMessage,
    telerivet_message_id: telerivetMessageId,
    sender_number: senderNumber,
    receiver_number: receiverNumber,

    webhook_event: webhookEvent,
    direction
  };
}

// Extract parts of the SMS
const locationName = match[1].trim();
const assetName = match[2].trim();
const eventText = match[3].trim().toUpperCase();
const dateTimeText = match[4].trim();

// Datalogger format is MM/DD/YYYY HH:mm:ss
const eventDateTime = DateTime.fromFormat(
  dateTimeText,
  'MM/dd/yyyy HH:mm:ss',
  {
    zone: 'Asia/Kolkata',
    locale: 'en'
  }
);

// Validate the embedded date and time
if (!eventDateTime.isValid) {
  return {
    parsed_successfully: false,
    parse_error: `Invalid datalogger date/time: ${dateTimeText}`,

    raw_message: rawMessage,
    telerivet_message_id: telerivetMessageId,
    sender_number: senderNumber,
    receiver_number: receiverNumber
  };
}

// Standardise the event name
const eventType =
  eventText === 'FAILURE'
    ? 'FAILURE'
    : 'RESTORED';

// Status generated from the SMS
const status =
  eventType === 'FAILURE'
    ? 'OPEN'
    : 'RECTIFIED';

// A standard key used to match Failure and Restored SMS
const assetKey = `${locationName}|${assetName}`
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

return {
  parsed_successfully: true,

  telerivet_message_id: telerivetMessageId,
  sender_number: senderNumber,
  receiver_number: receiverNumber,

  location_name: locationName,
  asset_name: assetName,
  asset_key: assetKey,

  event_type: eventType,
  status,

  event_time_text: dateTimeText,
  event_time: eventDateTime.toISO(),
  event_time_sql: eventDateTime.toFormat('yyyy-MM-dd HH:mm:ss'),

  raw_message: rawMessage,

  webhook_event: webhookEvent,
  direction,

  processed_at: DateTime.now()
    .setZone('Asia/Kolkata')
    .toISO()
};

const rows = $input.all().map(item => item.json);

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const formatDuration = (value) => {
  let seconds = Math.max(0, Number(value || 0));

  const days = Math.floor(seconds / 86400);
  seconds %= 86400;

  const hours = Math.floor(seconds / 3600);
  seconds %= 3600;

  const minutes = Math.floor(seconds / 60);
  seconds = Math.floor(seconds % 60);

  return [
    days ? `${days}d` : '',
    hours ? `${hours}h` : '',
    minutes ? `${minutes}m` : '',
    `${seconds}s`,
  ].filter(Boolean).join(' ');
};

const first = rows[0] || {};

const totalOpen = Number(first.total_open_faults || 0);
const failuresToday = Number(first.failures_today || 0);
const rectifiedToday = Number(first.rectified_today || 0);
const averageDowntime = Number(first.average_downtime_seconds || 0);

const openFaults = rows.filter(row => row.status === 'OPEN');
const rectifiedFaults = rows
  .filter(row => row.status === 'RECTIFIED')
  .slice(0, 100);

const createRows = (records, isOpen) => {
  if (!records.length) {
    return `
      <tr>
        <td colspan="6" class="empty">
          ${isOpen
            ? 'No open faults. All monitored assets are restored.'
            : 'No rectified incidents found.'}
        </td>
      </tr>
    `;
  }

  return records.map(row => `
    <tr>
      <td class="location">${escapeHtml(row.location_name)}</td>
      <td>${escapeHtml(row.asset_name)}</td>
      <td>${escapeHtml(row.failure_time_ist || '—')}</td>

      ${isOpen ? '' : `
        <td>${escapeHtml(row.restoration_time_ist || '—')}</td>
      `}

      <td class="duration">
        ${formatDuration(row.effective_downtime_seconds)}
      </td>

      <td>
        <span class="status ${isOpen ? 'open' : 'rectified'}">
          ${escapeHtml(row.status)}
        </span>
      </td>
    </tr>
  `).join('');
};

