          Datalogger Fault Monitoring System
        </h1>

        <p>
          Live failure, restoration and downtime monitoring
        </p>
      </div>

      <div class="live">
        <span class="live-dot"></span>
        LIVE · AUTO REFRESH 20s
      </div>
    </header>

    <section class="cards">
      <article class="card red">
        <span>Open Faults</span>
        <strong>${totalOpen}</strong>
      </article>

      <article class="card">
        <span>Failures Today</span>
        <strong>${failuresToday}</strong>
      </article>

      <article class="card green">
        <span>Rectified Today</span>
        <strong>${rectifiedToday}</strong>
      </article>

      <article class="card">
        <span>Average Downtime</span>
        <strong>${formatDuration(averageDowntime)}</strong>
      </article>
    </section>

    <div class="toolbar">
      <input
        id="searchBox"
        type="search"
        placeholder="Search location or asset..."
        oninput="filterRows()"
      >

      <select
        id="statusFilter"
        onchange="filterRows()"
      >
        <option value="ALL">All statuses</option>
        <option value="OPEN">Open</option>
        <option value="RECTIFIED">Rectified</option>
      </select>

      <button onclick="window.location.reload()">
        Refresh now
      </button>
    </div>

    <section class="panel alert">
      <div class="panel-heading">
        <div>
          <p class="eyebrow">ATTENTION REQUIRED</p>
          <h2>Live Open Faults</h2>
        </div>

        <div class="count">
          ${openFaults.length}
        </div>
      </div>

      <div class="table-wrapper">
        <table id="openTable">
          <thead>
            <tr>
              <th>Location</th>
              <th>Asset</th>
              <th>Failure Time (IST)</th>
              <th>Open Duration</th>
              <th>Status</th>
            </tr>
          </thead>

          <tbody>
            ${createRows(openFaults, true)}
          </tbody>
        </table>
      </div>
    </section>

    <section class="panel">
      <div class="panel-heading">
        <div>
          <p class="eyebrow">RESTORATION HISTORY</p>
          <h2>Recently Rectified Faults</h2>
        </div>
      </div>

      <div class="table-wrapper">
        <table id="rectifiedTable">
          <thead>
            <tr>
              <th>Location</th>
              <th>Asset</th>
              <th>Failure Time (IST)</th>
              <th>Restoration Time (IST)</th>
              <th>Downtime</th>
              <th>Status</th>
            </tr>
          </thead>

          <tbody>
            ${createRows(rectifiedFaults, false)}
          </tbody>
        </table>
      </div>
    </section>

    <footer>
      Generated by n8n · Data source: Neon PostgreSQL
    </footer>
  </main>

  <script>
    function filterRows() {
      const search =
        document
          .getElementById('searchBox')
          .value
          .toLowerCase();

      const status =
        document
          .getElementById('statusFilter')
          .value;

      const rows =
        document.querySelectorAll(
          '#openTable tbody tr, #rectifiedTable tbody tr'
        );

      rows.forEach(row => {
        const text = row.innerText.toLowerCase();

        const rowStatus =
          text.includes('rectified')
            ? 'RECTIFIED'
            : text.includes('open')
              ? 'OPEN'
              : '';

        const searchMatch =
          !search || text.includes(search);

        const statusMatch =
          status === 'ALL' || rowStatus === status;

        row.style.display =
          searchMatch && statusMatch
            ? ''
            : 'none';
      });
    }

    setTimeout(() => {
      window.location.reload();
    }, 20000);
  </script>
